  <!-- Script Modules -->
  <script type="module">
    import { removeBackground } from 'https://cdn.jsdelivr.net/npm/@imgly/background-removal/+esm';

    // State Variables
    let imgState = {
      x: 0,
      y: 0,
      scale: 1.0,
      originalWidth: 0,
      originalHeight: 0,
      hasImage: false
    };

    // DOM Elements
    const imageUpload = document.getElementById('image-upload');
    const zoomSlider = document.getElementById('zoom-slider');
    const nameInput = document.getElementById('name-input');
    const namePreview = document.getElementById('name-preview');
    const occupationInput = document.getElementById('occupation-input');
    const occupationPreview = document.getElementById('occupation-preview');
    const quoteInput = document.getElementById('quote-input');
    const quoteCanvasPreview = document.getElementById('quote-canvas-preview');
    const quoteContainer = document.getElementById('quote-container');
    const quoteCharCount = document.getElementById('quote-char-count');
    const userAvatarImg = document.getElementById('user-avatar-img');
    const imageFrame = document.getElementById('image-frame');
    const loadingOverlay = document.getElementById('loading-overlay');
    const loadingText = document.getElementById('loading-text');
    const downloadBtn = document.getElementById('download-btn');
    const resetBtn = document.getElementById('reset-btn');
    const avatarCanvas = document.getElementById('avatar-canvas');
    const previewContainer = document.querySelector('.preview-container');
    const badgeTopNum = document.getElementById('badge-top-num');

    function generateBadgeNumber() {
      const num = Math.floor(Math.random() * 349) + 1;
      badgeTopNum.textContent = String(num).padStart(3, '0');
    }

    function drawQuoteOnCanvas(text, canvas, maxWidth) {
      const ctx = canvas.getContext('2d');
      
      // Temporary setup to split text into lines
      ctx.font = "italic 700 30px 'Poppins', sans-serif";
      
      const words = text.split(' ');
      let lines = [];
      let currentLine = '';
      
      for (let n = 0; n < words.length; n++) {
        let testLine = currentLine + words[n] + ' ';
        let metrics = ctx.measureText(testLine);
        let testWidth = metrics.width;
        if (testWidth > maxWidth && n > 0) {
          lines.push(currentLine.trim());
          currentLine = words[n] + ' ';
        } else {
          currentLine = testLine;
        }
      }
      lines.push(currentLine.trim());
      
      // Calculate dynamic canvas size
      const lineHeight = 48; // 1.6 * 30px
      canvas.width = 350;
      canvas.height = lines.length * lineHeight + 20;
      
      // Set properties again after resizing canvas (which resets properties)
      ctx.font = "italic 700 30px 'Poppins', sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "top";
      ctx.strokeStyle = '#ffffff';
      ctx.lineWidth = 18; // Very thick stroke
      ctx.lineJoin = 'round';
      ctx.miterLimit = 2;
      ctx.fillStyle = '#315404'; // var(--primary-dark)
      
      const startY = 10;
      for (let i = 0; i < lines.length; i++) {
        const y = startY + (i * lineHeight);
        const x = canvas.width - 10; // Right aligned with padding
        
        // Draw stroke (underneath)
        ctx.strokeText(lines[i], x, y);
        // Draw fill (on top)
        ctx.fillText(lines[i], x, y);
      }
    }

    // Default Configuration & Responsive Scaling
    const CANVAS_WIDTH = 1080;
    const CANVAS_HEIGHT = 1350;

    function initResponsiveScale() {
      const resizeObserver = new ResizeObserver(entries => {
        for (let entry of entries) {
          const width = entry.contentRect.width;
          const scale = width / CANVAS_WIDTH;
          avatarCanvas.style.setProperty('--preview-scale', scale);
        }
      });
      resizeObserver.observe(previewContainer);
    }

    // Initialize scaling & badge number
    initResponsiveScale();
    generateBadgeNumber();

    // Enable drag and pinch-to-zoom on the user image
    interact(userAvatarImg).gesturable({
      listeners: {
        move(event) {
          imgState.scale = imgState.scale * (1 + event.ds);
          
          // Constrain zoom to range of slider
          if (imgState.scale < 0.1) imgState.scale = 0.1;
          if (imgState.scale > 3.0) imgState.scale = 3.0;
          
          zoomSlider.value = imgState.scale;
          applyImageTransform();
        }
      }
    }).draggable({
      listeners: {
        move(event) {
          imgState.x += event.dx;
          imgState.y += event.dy;
          applyImageTransform();
        }
      }
    });

    function applyImageTransform() {
      userAvatarImg.style.transform = `translate(${imgState.x}px, ${imgState.y}px) scale(${imgState.scale})`;
    }

    // Connect range slider to zoom
    zoomSlider.addEventListener('input', (e) => {
      imgState.scale = parseFloat(e.target.value);
      applyImageTransform();
    });

    // Image Upload Handling with @imgly/background-removal
    imageUpload.addEventListener('change', async (e) => {
      const file = e.target.files[0];
      if (!file) return;

      // Reset image state
      userAvatarImg.src = '';
      userAvatarImg.style.display = 'none';
      imgState.hasImage = false;

      // Show loader
      loadingText.textContent = "Removing background...";
      loadingOverlay.classList.add('active');

      try {
        // Run background removal
        const processedBlob = await removeBackground(file, {
          model: 'medium', // high accuracy
          output: {
            type: 'image/png',
            quality: 0.8
          }
        });

        // Convert blob to Base64 Data URL for html2canvas reliability
        const reader = new FileReader();
        reader.readAsDataURL(processedBlob);
        reader.onloadend = () => {
          const base64data = reader.result;
          userAvatarImg.src = base64data;
          userAvatarImg.style.display = 'block';
          
          // Reset positioning
          imgState.x = 0;
          imgState.y = 0;
          imgState.scale = 1.0;
          zoomSlider.value = 1.0;
          zoomSlider.disabled = false;
          imgState.hasImage = true;

          // Set initial size and center the image in the frame
          const img = new Image();
          img.src = base64data;
          img.onload = () => {
            imgState.originalWidth = img.width;
            imgState.originalHeight = img.height;

            // Scale to fill frame beautifully
            const frameWidth = 980;
            const frameHeight = 785;
            
            const scaleX = frameWidth / img.width;
            const scaleY = frameHeight / img.height;
            const fillScale = Math.max(scaleX, scaleY);
            
            imgState.scale = fillScale;
            zoomSlider.value = fillScale;

            // Center position
            imgState.x = (frameWidth - img.width) / 2;
            imgState.y = (frameHeight - img.height) / 2;

            applyImageTransform();
            loadingOverlay.classList.remove('active');
          };
        };

      } catch (error) {
        console.error("Background removal failed: ", error);
        alert("Failed to remove background automatically. Please try uploading a different photo.");
        loadingOverlay.classList.remove('active');
      }
    });

    // Realtime Input Handlers
    nameInput.addEventListener('input', (e) => {
      let val = e.target.value;
      
      // Auto-restrict name typing to maximum 2 words
      const words = val.trim().split(/\s+/);
      if (words.length > 2) {
        // Reconstruct only the first two words
        val = words.slice(0, 2).join(' ');
        nameInput.value = val;
      }

      // Check if it wraps into 2 words
      const displayWords = val.split(/\s+/).filter(w => w.length > 0);
      if (displayWords.length === 2) {
        namePreview.innerHTML = `${displayWords[0]}<br>${displayWords[1]}`;
      } else {
        namePreview.textContent = val;
      }
    });

    occupationInput.addEventListener('input', (e) => {
      const val = e.target.value.toUpperCase();
      occupationPreview.textContent = val;
    });

    quoteInput.addEventListener('input', (e) => {
      const val = e.target.value;
      const remaining = 120 - val.length;
      quoteCharCount.textContent = `${remaining} characters remaining`;

      if (val.trim() === "") {
        quoteContainer.style.display = 'none';
      } else {
        quoteContainer.style.display = 'flex';
        drawQuoteOnCanvas(val, quoteCanvasPreview, 340);
      }
    });

    // Reset Form and Position
    resetBtn.addEventListener('click', () => {
      imageUpload.value = '';
      userAvatarImg.src = '';
      userAvatarImg.style.display = 'none';
      imgState = {
        x: 0,
        y: 0,
        scale: 1.0,
        originalWidth: 0,
        originalHeight: 0,
        hasImage: false
      };
      zoomSlider.value = 1.0;
      zoomSlider.disabled = true;

      nameInput.value = '';
      namePreview.textContent = '';

      occupationInput.value = '';
      occupationPreview.textContent = '';

      quoteInput.value = '';
      const ctx = quoteCanvasPreview.getContext('2d');
      ctx.clearRect(0, 0, quoteCanvasPreview.width, quoteCanvasPreview.height);
      quoteContainer.style.display = 'none';
      quoteCharCount.textContent = '120 characters remaining';
      generateBadgeNumber();
    });

    // Download Avatar
    downloadBtn.addEventListener('click', () => {
      // Validate compulsory fields
      if (!imgState.hasImage) {
        alert("Please upload a profile photo first.");
        return;
      }
      if (!nameInput.value.trim()) {
        alert("Please enter your name first.");
        return;
      }
      if (!occupationInput.value.trim()) {
        alert("Please enter your occupation first.");
        return;
      }

      // Show processing loader
      loadingText.textContent = "Generating high resolution download...";
      loadingOverlay.classList.add('active');

      // Temporarily detach preview responsive scale during render so html2canvas renders full resolution
      const originalScale = avatarCanvas.style.getPropertyValue('--preview-scale');
      avatarCanvas.style.removeProperty('--preview-scale');

      // Execute render
      html2canvas(avatarCanvas, {
        width: CANVAS_WIDTH,
        height: CANVAS_HEIGHT,
        scale: 1, // Enforce 1:1 render scale
        useCORS: true,
        allowTaint: true,
        backgroundColor: null,
        logging: false
      }).then(canvas => {
        // Restore responsive scale property
        avatarCanvas.style.setProperty('--preview-scale', originalScale);
        loadingOverlay.classList.remove('active');

        // Download link trigger
        const link = document.createElement('a');
        link.download = `${nameInput.value.trim().toLowerCase().replace(/\s+/g, '_')}_avatar.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
      }).catch(err => {
        console.error("Canvas render failed:", err);
        // Restore scale in case of failure
        avatarCanvas.style.setProperty('--preview-scale', originalScale);
        loadingOverlay.classList.remove('active');
        alert("An error occurred while generating the image. Please try again.");
      });
    });
  </script>

<?php wp_footer(); ?>
</body>
</html>